// Replaces the theme's 5.5 MB single-file Mermaid. The theme concatenates this file with its dark-mode glue and calls
// mermaid.initialize()/run(); this facade loads the chunked ESM build on the first run(), so a page fetches only the
// diagram types it uses (the chat widget loads the same files).
(() => {
    let config = {};
    let engine;
    globalThis.mermaid = {
        initialize(options) {
            config = options;
        },
        async run(options) {
            engine ??= import('/vendor/mermaid/mermaid.esm.min.mjs').then((module) => module.default);
            const mermaid = await engine;
            mermaid.initialize({ startOnLoad: false, ...config });
            return mermaid.run(options);
        },
    };
})();
